const API="https://vkzxknpveoghhccgwaan.supabase.co/rest/v1";
const KEY="sb_publishable_N2Hxy1FWrPCbUz6ifyQx6w_fqpWal1l";
const H={apikey:KEY,Authorization:`Bearer ${KEY}`,"Content-Type":"application/json"};
async function db(table,{method="GET",params=[],body,returning=false}={}){const qs=params.length?`?${params.join("&")}`:"";const r=await fetch(`${API}/${table}${qs}`,{method,headers:{...H,...(returning?{Prefer:"return=representation"}:{})},body:body===undefined?undefined:JSON.stringify(body)});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw new Error(d?.message||d?.details||d?.hint||t||`HTTP ${r.status}`);return d}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const cats={speaking:{label:"Speaking",icon:"🎙️",description:"話す練習を、自分のテーマごとに整理できます。"},listening:{label:"Listening",icon:"🎧",description:"Podcast・音声教材をテーマごとに整理できます。"},writing:{label:"Writing",icon:"✍️",description:"英作文・日記・添削用のタブを整理できます。"},reading:{label:"Reading",icon:"📖",description:"英文読解・記事・教材をテーマごとに整理できます。"}};
const defaults={speaking:"My Speaking",listening:"My Listening",writing:"My Writing",reading:"My Reading"};
let state={tabs:{speaking:[],listening:[],writing:[],reading:[]},activeCategory:"speaking",activeSubTabs:{}};
let currentArticleId=null,currentDetailId=null,currentPodcastId=null,currentListeningDetailId=null;
const UI_KEY="english-study-ui-v7";
function dlg(id){const e=$("#"+id);if(e&&!e.open)e.showModal()}function closeDlg(id){const e=$("#"+id);if(e?.open)e.close()}
function saveUI(){localStorage.setItem(UI_KEY,JSON.stringify({activeCategory:state.activeCategory,activeSubTabs:state.activeSubTabs}))}
function restoreUI(){try{const x=JSON.parse(localStorage.getItem(UI_KEY)||"null");if(x){state.activeCategory=x.activeCategory||"speaking";state.activeSubTabs=x.activeSubTabs||{}}}catch{}}
function tabs(){return state.tabs[state.activeCategory]||[]}function activeTab(){const t=tabs();return t.find(x=>x.id===state.activeSubTabs[state.activeCategory])||t[0]}
function showError(e){console.error(e);alert(`保存に失敗しました。\n${e.message||e}`)}

async function load(){
  for(const c of Object.keys(cats)){
    let rows=await db("study_tabs",{params:[`category=eq.${encodeURIComponent(c)}`,"select=id,name,category,created_at","order=created_at.asc"]});
    if(!rows.length)rows=await db("study_tabs",{method:"POST",body:{category:c,name:defaults[c]},returning:true});
    state.tabs[c]=rows;
    if(c==="reading")rows.forEach(t=>t.articles=[]);
    if(c==="listening")rows.forEach(t=>t.podcasts=[]);
  }
  const articles=await db("reading_articles",{params:["select=id,tab_id,title,url,memo,article_date,english_text,japanese_translation,grammar_notes,created_at","order=created_at.desc"]});
  const items=await db("learning_items",{params:["select=id,article_id,term,meaning,how,example,context,level,last_reviewed,created_at","order=created_at.asc"]});
  const amap=new Map(articles.map(a=>[a.id,{id:a.id,title:a.title,url:a.url||"",memo:a.memo||"",date:a.article_date||"",englishText:a.english_text||"",translation:a.japanese_translation||"",grammar:a.grammar_notes||"",items:[]} ]));
  items.forEach(x=>amap.get(x.article_id)?.items.push({id:x.id,term:x.term,meaning:x.meaning,context:x.context||"",how:x.how||"",example:x.example||""}));
  state.tabs.reading.forEach(t=>t.articles=articles.filter(a=>a.tab_id===t.id).map(a=>amap.get(a.id)).filter(Boolean));

  const podcasts=await db("listening_podcasts",{params:["select=id,tab_id,title,url,memo,podcast_date,transcript,japanese_translation,grammar_notes,created_at","order=created_at.desc"]});
  const litems=await db("listening_items",{params:["select=id,podcast_id,term,meaning,context,how,example,created_at","order=created_at.asc"]});
  const pmap=new Map(podcasts.map(p=>[p.id,{id:p.id,title:p.title,url:p.url||"",memo:p.memo||"",date:p.podcast_date||"",englishText:p.transcript||"",translation:p.japanese_translation||"",grammar:p.grammar_notes||"",items:[]} ]));
  litems.forEach(x=>pmap.get(x.podcast_id)?.items.push({id:x.id,term:x.term,meaning:x.meaning,context:x.context||"",how:x.how||"",example:x.example||""}));
  state.tabs.listening.forEach(t=>t.podcasts=podcasts.filter(p=>p.tab_id===t.id).map(p=>pmap.get(p.id)).filter(Boolean));

  restoreUI();
  for(const c of Object.keys(cats)){if(!state.tabs[c].some(t=>t.id===state.activeSubTabs[c]))state.activeSubTabs[c]=state.tabs[c][0]?.id}
  render();
}

function render(){
  $$(".main-tab").forEach(b=>b.classList.toggle("active",b.dataset.mainTab===state.activeCategory));
  const list=$("#subTabs");list.innerHTML="";const ts=tabs(),at=activeTab();
  ts.forEach(t=>{const b=document.createElement("button");b.type="button";b.className=`sub-tab${t.id===at?.id?" active":""}`;b.innerHTML=`<span>${esc(t.name)}</span>`;if(ts.length>1){const x=document.createElement("button");x.type="button";x.className="close-sub";x.textContent="×";x.onclick=e=>{e.stopPropagation();removeTab(t.id)};b.appendChild(x)}b.onclick=()=>{state.activeSubTabs[state.activeCategory]=t.id;saveUI();render()};list.appendChild(b)});
  const c=cats[state.activeCategory];$("#workspaceKicker").textContent=c.label.toUpperCase();$("#workspaceTitle").textContent=c.label;$("#contentIcon").textContent=c.icon;$("#contentTitle").textContent=`${at?.name||c.label} を始めよう`;$("#contentDescription").textContent=c.description;
  const reading=state.activeCategory==="reading",listening=state.activeCategory==="listening";
  $("#genericContent").classList.toggle("hidden",reading||listening);$("#readingContent").classList.toggle("hidden",!reading);$("#listeningContent").classList.toggle("hidden",!listening);$("#newArticleHeaderButton").classList.toggle("hidden",!reading);$("#newPodcastHeaderButton").classList.toggle("hidden",!listening);
  if(reading&&at)renderArticles(at);if(listening&&at)renderPodcasts(at);
  $("#tabCount").textContent=Object.values(state.tabs).reduce((n,x)=>n+x.length,0);
  const count=state.tabs.reading.reduce((n,t)=>n+(t.articles||[]).reduce((m,a)=>m+(a.items?.length||0),0),0)+state.tabs.listening.reduce((n,t)=>n+(t.podcasts||[]).reduce((m,p)=>m+(p.items?.length||0),0),0);
  $("#studyMinutes").innerHTML=`${count} <small>items</small>`;
}
function renderArticles(at){$("#readingTabTitle").textContent=at.name;const as=at.articles||[];$("#readingEmpty").classList.toggle("hidden",as.length>0);const box=$("#articleList");box.innerHTML="";as.forEach(a=>{const n=a.items?.length||0,card=document.createElement("article");card.className="article-card";card.innerHTML=`<div class="article-card-top"><div><span class="article-date">${esc(a.date)}</span><h4>${esc(a.title)}</h4><p>${esc(a.memo)}</p></div><span class="article-count">${n} items</span></div><div class="article-actions">${a.url?`<a class="secondary-button link-button" href="${esc(a.url)}" target="_blank" rel="noopener">BBC記事 ↗</a>`:""}<button class="new-button" data-open="${a.id}">学習ページを開く</button><button class="secondary-button" data-bundle="${a.id}">編集 / ChatGPT一括登録</button></div>`;box.appendChild(card)})}
function renderPodcasts(at){$("#listeningTabTitle").textContent=at.name;const ps=at.podcasts||[];$("#listeningEmpty").classList.toggle("hidden",ps.length>0);const box=$("#podcastList");box.innerHTML="";ps.forEach(p=>{const n=p.items?.length||0,card=document.createElement("article");card.className="article-card";card.innerHTML=`<div class="article-card-top"><div><span class="article-date">${esc(p.date)}</span><h4>${esc(p.title)}</h4><p>${esc(p.memo)}</p></div><span class="article-count">${n} items</span></div><div class="article-actions">${p.url?`<a class="secondary-button link-button" href="${esc(p.url)}" target="_blank" rel="noopener">Podcastを開く ↗</a>`:""}<button class="new-button" data-podcast-open="${p.id}">学習ページを開く</button><button class="secondary-button" data-podcast-bundle="${p.id}">編集 / ChatGPT一括登録</button></div>`;box.appendChild(card)})}

async function addTab(){const c=state.activeCategory,name=prompt(`${cats[c].label} に追加するタブ名`,c==="reading"?"BBC News":c==="listening"?"Podcast":"New lesson");if(!name?.trim())return;try{const [t]=await db("study_tabs",{method:"POST",body:{category:c,name:name.trim()},returning:true});if(c==="reading")t.articles=[];if(c==="listening")t.podcasts=[];state.tabs[c].push(t);state.activeSubTabs[c]=t.id;saveUI();render()}catch(e){showError(e)}}
async function removeTab(id){const ts=tabs();if(ts.length<=1)return;const t=ts.find(x=>x.id===id);if(!t||!confirm(`「${t.name}」を削除しますか？`))return;try{await db("study_tabs",{method:"DELETE",params:[`id=eq.${encodeURIComponent(id)}`]});const i=ts.indexOf(t);ts.splice(i,1);state.activeSubTabs[state.activeCategory]=ts[Math.max(0,i-1)].id;saveUI();render()}catch(e){showError(e)}}

function parseBundle(text){const norm=text.replace(/\r/g,"");const sections={};const re=/【(英文|翻訳|単語・表現|文法・構文)】/g;let m,last=null,lastPos=0;while((m=re.exec(norm))){if(last)sections[last]=norm.slice(lastPos,m.index).trim();last=m[1];lastPos=re.lastIndex}if(last)sections[last]=norm.slice(lastPos).trim();const vocab=(sections["単語・表現"]||"").split(/\n+/).map(x=>x.trim()).filter(Boolean).filter(x=>!/^[-|\s]*$/.test(x)).map(line=>{const p=line.split(/\t|\s*\|\s*/).map(x=>x.trim()).filter(Boolean);if(p[0]?.includes("単語")&&p[1]?.includes("意味"))return null;return p.length>=2?{term:p[0],meaning:p[1],context:p[2]||"",how:p[3]||"",example:p[4]||""}:null}).filter(Boolean);return{english:sections["英文"]||"",translation:sections["翻訳"]||"",grammar:sections["文法・構文"]||"",vocab}}
function formatBundle(item){const vocab=(item.items||[]).map(x=>[x.term,x.meaning,x.context||"",x.how||"",x.example||""].join(" | ")).join("\n");return `【英文】\n${item.englishText||""}\n\n【翻訳】\n${item.translation||""}\n\n【単語・表現】\n${vocab}\n\n【文法・構文】\n${item.grammar||""}`}
async function mergeVocab(table,foreignKey,parentId,currentItems,incoming){const byTerm=new Map((currentItems||[]).map(x=>[String(x.term||"").trim().toLowerCase(),x]));for(const v of incoming){const key=String(v.term||"").trim().toLowerCase();const existing=byTerm.get(key);const payload={term:v.term,meaning:v.meaning,context:v.context||null,how:v.how||null,example:v.example||null};if(existing){await db(table,{method:"PATCH",params:[`id=eq.${encodeURIComponent(existing.id)}`],body:payload});Object.assign(existing,{term:v.term,meaning:v.meaning,context:v.context||"",how:v.how||"",example:v.example||""})}else{const rows=await db(table,{method:"POST",body:{[foreignKey]:parentId,...payload},returning:true});const created=rows?.[0];if(created){const item={id:created.id,term:created.term,meaning:created.meaning,context:created.context||"",how:created.how||"",example:created.example||""};currentItems.push(item);byTerm.set(key,item)}}}}

function openArticle(){$("#articleForm").reset();dlg("articleDialog");$("#articleTitle").focus()}
async function saveArticle(e){e.preventDefault();const t=activeTab();try{const [a]=await db("reading_articles",{method:"POST",body:{tab_id:t.id,title:$("#articleTitle").value.trim(),url:$("#articleUrl").value.trim()||null,memo:$("#articleMemo").value.trim()||null},returning:true});t.articles||=[];t.articles.unshift({id:a.id,title:a.title,url:a.url||"",memo:a.memo||"",date:a.article_date||"",englishText:"",translation:"",grammar:"",items:[]});closeDlg("articleDialog");render()}catch(e){showError(e)}}
function findArticle(id){for(const t of state.tabs.reading){const a=(t.articles||[]).find(x=>x.id===id);if(a)return a}return null}
async function saveBundle(e){e.preventDefault();const a=findArticle(currentArticleId);if(!a)return;const p=parseBundle($("#bundleInput").value);if(!p.english&&!p.translation&&!p.grammar&&!p.vocab.length)return alert("【英文】【翻訳】【単語・表現】【文法・構文】の見出し付きで入力してください。");try{await db("reading_articles",{method:"PATCH",params:[`id=eq.${encodeURIComponent(a.id)}`],body:{english_text:p.english||null,japanese_translation:p.translation||null,grammar_notes:p.grammar||null}});a.englishText=p.english;a.translation=p.translation;a.grammar=p.grammar;await mergeVocab("learning_items","article_id",a.id,a.items,p.vocab);closeDlg("bundleDialog");render();openDetail(a.id)}catch(e){showError(e)}}
function openDetail(id){const a=findArticle(id);if(!a)return;currentDetailId=id;$("#detailTitle").textContent=a.title;$("#detailSource").innerHTML=a.url?`<a href="${esc(a.url)}" target="_blank" rel="noopener">BBC記事を開く ↗</a>`:"";drawDetailTab("english");dlg("detailDialog")}
function drawDetailTab(tab){const a=findArticle(currentDetailId);$$("[data-detail-tab]").forEach(b=>b.classList.toggle("active",b.dataset.detailTab===tab));drawBundleBody($("#detailBody"),a,tab,"記事中の使われ方")}

function openPodcast(){$("#podcastForm").reset();dlg("podcastDialog");$("#podcastTitle").focus()}
async function savePodcast(e){e.preventDefault();const t=activeTab();try{const [p]=await db("listening_podcasts",{method:"POST",body:{tab_id:t.id,title:$("#podcastTitle").value.trim(),url:$("#podcastUrl").value.trim()||null,memo:$("#podcastMemo").value.trim()||null},returning:true});t.podcasts||=[];t.podcasts.unshift({id:p.id,title:p.title,url:p.url||"",memo:p.memo||"",date:p.podcast_date||"",englishText:"",translation:"",grammar:"",items:[]});closeDlg("podcastDialog");render()}catch(e){showError(e)}}
function findPodcast(id){for(const t of state.tabs.listening){const p=(t.podcasts||[]).find(x=>x.id===id);if(p)return p}return null}
async function saveListeningBundle(e){e.preventDefault();const p=findPodcast(currentPodcastId);if(!p)return;const x=parseBundle($("#listeningBundleInput").value);if(!x.english&&!x.translation&&!x.grammar&&!x.vocab.length)return alert("【英文】【翻訳】【単語・表現】【文法・構文】の見出し付きで入力してください。");try{await db("listening_podcasts",{method:"PATCH",params:[`id=eq.${encodeURIComponent(p.id)}`],body:{transcript:x.english||null,japanese_translation:x.translation||null,grammar_notes:x.grammar||null}});p.englishText=x.english;p.translation=x.translation;p.grammar=x.grammar;await mergeVocab("listening_items","podcast_id",p.id,p.items,x.vocab);closeDlg("listeningBundleDialog");render();openListeningDetail(p.id)}catch(e){showError(e)}}
function openListeningDetail(id){const p=findPodcast(id);if(!p)return;currentListeningDetailId=id;$("#listeningDetailTitle").textContent=p.title;$("#listeningDetailSource").innerHTML=p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener">Podcastを開く ↗</a>`:"";drawListeningDetailTab("english");dlg("listeningDetailDialog")}
function drawListeningDetailTab(tab){const p=findPodcast(currentListeningDetailId);$$("[data-listening-detail-tab]").forEach(b=>b.classList.toggle("active",b.dataset.listeningDetailTab===tab));drawBundleBody($("#listeningDetailBody"),p,tab,"Podcast中の使われ方")}
function drawBundleBody(body,item,tab,contextLabel){if(tab==="english")body.innerHTML=`<div class="reading-text">${item.englishText?esc(item.englishText).replace(/\n/g,"<br>"):"まだ英文が登録されていません。"}</div>`;if(tab==="translation")body.innerHTML=`<div class="reading-text">${item.translation?esc(item.translation).replace(/\n/g,"<br>"):"まだ翻訳が登録されていません。"}</div>`;if(tab==="vocab")body.innerHTML=item.items.length?`<div class="vocab-table"><div class="vocab-row head"><span>単語・表現</span><span>意味</span><span>${contextLabel}</span></div>${item.items.map(x=>`<div class="vocab-row"><strong>${esc(x.term)}</strong><span>${esc(x.meaning)}</span><span>${esc(x.context||x.example||"")}</span></div>`).join("")}</div>`:`<p class="empty-note">まだ単語・表現がありません。</p>`;if(tab==="grammar")body.innerHTML=`<div class="grammar-text">${item.grammar?esc(item.grammar).replace(/\n/g,"<br>"):"まだ文法・構文が登録されていません。"}</div>`}

$("#newTabButton").onclick=addTab;$$('.main-tab').forEach(b=>b.onclick=()=>{state.activeCategory=b.dataset.mainTab;saveUI();render()});$$('[data-close]').forEach(b=>b.onclick=()=>closeDlg(b.dataset.close));
$("#newArticleButton").onclick=openArticle;$("#newArticleHeaderButton").onclick=openArticle;$("#articleForm").onsubmit=saveArticle;$("#bundleForm").onsubmit=saveBundle;$("#articleList").onclick=e=>{const open=e.target.closest('[data-open]')?.dataset.open,bundle=e.target.closest('[data-bundle]')?.dataset.bundle;if(open)openDetail(open);if(bundle){const a=findArticle(bundle);if(!a)return;currentArticleId=bundle;$("#bundleInput").value=formatBundle(a);dlg("bundleDialog");$("#bundleInput").focus()}};$$('[data-detail-tab]').forEach(b=>b.onclick=()=>drawDetailTab(b.dataset.detailTab));
$("#newPodcastButton").onclick=openPodcast;$("#newPodcastHeaderButton").onclick=openPodcast;$("#podcastForm").onsubmit=savePodcast;$("#listeningBundleForm").onsubmit=saveListeningBundle;$("#podcastList").onclick=e=>{const open=e.target.closest('[data-podcast-open]')?.dataset.podcastOpen,bundle=e.target.closest('[data-podcast-bundle]')?.dataset.podcastBundle;if(open)openListeningDetail(open);if(bundle){const p=findPodcast(bundle);if(!p)return;currentPodcastId=bundle;$("#listeningBundleInput").value=formatBundle(p);dlg("listeningBundleDialog");$("#listeningBundleInput").focus()}};$$('[data-listening-detail-tab]').forEach(b=>b.onclick=()=>drawListeningDetailTab(b.dataset.listeningDetailTab));
$("#emailShareButton")?.addEventListener("click",async()=>{const url="https://gd0627zkrb-droid.github.io/english-study-app/",text=`英語学習用のサイトです。\n${url}`;if(navigator.share){try{await navigator.share({title:"English Study",text,url});return}catch{}}location.href=`mailto:?subject=${encodeURIComponent("English Study")}&body=${encodeURIComponent(text)}`});

try{await load()}catch(e){console.error(e);state.tabs={speaking:[{id:"offline-speaking",name:defaults.speaking}],listening:[{id:"offline-listening",name:defaults.listening,podcasts:[]}],writing:[{id:"offline-writing",name:defaults.writing}],reading:[{id:"offline-reading",name:defaults.reading,articles:[]}]};restoreUI();Object.keys(cats).forEach(c=>state.activeSubTabs[c]||=state.tabs[c][0].id);render()}